//! Handles stratification of Datalog programs

use petgraph::{algo, graphmap::DiGraphMap};
use std::collections::{HashMap, HashSet};
use std::slice::Iter;
use syn::Ident;

pub struct Strata {
    list: Vec<Vec<Ident>>,
    index: HashMap<Ident, usize>,
}

impl Strata {
    pub fn new(relations: HashSet<Ident>, dependencies: HashSet<(&Ident, &Ident)>) -> Self {
        // Build a directed graph where an edge from A to B means "A depends on B"
        let mut graph: DiGraphMap<&Ident, ()> = DiGraphMap::new();

        // Add all nodes (relations)
        for rel in &relations {
            graph.add_node(rel);
        }

        // Add edges from dependencies (goal -> fact means goal depends on fact)
        for (goal, fact) in &dependencies {
            graph.add_edge(goal, fact, ());
        }

        // Find strongly connected components
        let sccs = algo::tarjan_scc(&graph);

        // Build a map from each relation to its SCC index
        let mut relation_to_scc: HashMap<&Ident, usize> = HashMap::new();
        for (scc_idx, scc) in sccs.iter().enumerate() {
            for rel in scc {
                relation_to_scc.insert(rel, scc_idx);
            }
        }

        // Build SCC dependency graph (edge from SCC A to SCC B means A depends on B)
        let mut scc_graph: DiGraphMap<usize, ()> = DiGraphMap::new();
        for scc_idx in 0..sccs.len() {
            scc_graph.add_node(scc_idx);
        }

        for (goal, fact) in &dependencies {
            let goal_scc = relation_to_scc[goal];
            let fact_scc = relation_to_scc[fact];
            if goal_scc != fact_scc {
                scc_graph.add_edge(goal_scc, fact_scc, ());
            }
        }

        // Compute stratum level for each SCC using topological order
        let mut scc_level: HashMap<usize, usize> = HashMap::new();

        // Use reverse topological order: process nodes with no incoming edges first
        let mut processed = HashSet::new();
        let mut level = 0;

        loop {
            let mut any_added = false;
            for scc_idx in 0..sccs.len() {
                if processed.contains(&scc_idx) {
                    continue;
                }

                // Check if all dependencies of this SCC have been processed
                let mut all_deps_processed = true;
                for (_, dep_scc) in scc_graph.edges(scc_idx) {
                    if !processed.contains(&dep_scc) {
                        all_deps_processed = false;
                        break;
                    }
                }

                if all_deps_processed {
                    // Compute the level as max level of dependencies + 1
                    let mut max_dep_level = 0;
                    let mut has_deps = false;
                    for (_, dep_scc) in scc_graph.edges(scc_idx) {
                        has_deps = true;
                        max_dep_level = max_dep_level.max(scc_level[&dep_scc]);
                    }

                    let current_level = if has_deps { max_dep_level + 1 } else { 0 };
                    scc_level.insert(scc_idx, current_level);
                    processed.insert(scc_idx);
                    any_added = true;
                }
            }

            if !any_added {
                break;
            }
        }

        // Build the result: group relations by their stratum level
        let max_level = *scc_level.values().max().unwrap_or(&0);
        let mut list: Vec<Vec<Ident>> = vec![Vec::new(); max_level + 1];
        let mut index: HashMap<Ident, usize> = HashMap::new();

        for rel in relations {
            let scc_idx = relation_to_scc[&rel];
            let level = scc_level[&scc_idx];
            list[level].push(rel.clone());
            index.insert(rel, level);
        }

        Strata { list, index }
    }

    pub fn iter(&self) -> Iter<'_, Vec<Ident>> {
        self.list.iter()
    }

    pub fn find_relation(&self, rel: &Ident) -> usize {
        *self.index.get(rel).expect("key not found in stratum index")
    }
}
EOFFILE
